# Time a computation with @timer
@timer
def aggregate_sales():
    # Compute revenue if not already present
    if 'revenue' not in sales.columns:
        sales['revenue'] = sales['quantity'] * sales['unit_price'] * (1 - sales['discount'])
    return sales.groupby(['product', 'region']).agg(
        total_revenue=('revenue', 'sum'),
        avg_quantity=('quantity', 'mean'),
        order_count=('order_id', 'count')
    ).reset_index()

summary = aggregate_sales()
